// Custos stamp on submit. Adds one line to the owner's own comment or review:
//   prima-clock: YYYYMMDDHHMM UTC (stamped on submit)
// The time is the one GitHub recorded for the submit, in UTC, not the runner's clock.
//
// It edits the owner's words, so it is careful:
//   - only the repository owner, never a bot;
//   - never a body that carries the Claude Code footer (those are navigo posts under the owner's login),
//     reading the footer outside quotes and code, so a quoted footer in the owner's own reply does not block it;
//   - never a body that already has the stamp line, so it cannot run twice;
//   - never a body that ends inside an open code fence;
//   - the owner's own hand-typed stamps are left as they are.
//
// This module stamps. It never labels, seals or merges.

const { strip } = require('./cue-parser.js');

// The same two wordings the cue parser and the seal gate skip.
const FOOTERS = ['generated by [claude code]', 'generated with [claude code]'];
const STAMP_RE = /^prima-clock: \d{12} UTC \(stamped on submit\)\s*$/m;
// An opening or closing fence at the start of a line. The backtick is written \x60, as in cue-parser.js.
const FENCE_RE = /^ {0,3}(\x60\x60\x60|~~~)/gm;

const two = (n) => String(n).padStart(2, '0');

function primaClock(iso) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  return `${d.getUTCFullYear()}${two(d.getUTCMonth() + 1)}${two(d.getUTCDate())}${two(d.getUTCHours())}${two(d.getUTCMinutes())}`;
}

const carriesFooter = (body) => {
  const text = strip(String(body)).toLowerCase();
  return FOOTERS.some((f) => text.includes(f));
};

const endsInsideFence = (body) => (String(body).match(FENCE_RE) || []).length % 2 === 1;

const skip = (reason) => ({ action: 'skip', reason });

// input: { body, when, login, type, association, owner }. Returns { action: 'skip', reason } or { action: 'stamp', clock, body }.
function decide(input) {
  const { body, when, login, type, association, owner } = input;
  if (type === 'Bot') return skip('bot');
  const isOwner = association === 'OWNER' && String(login).toLowerCase() === String(owner).toLowerCase();
  if (!isOwner) return skip('not owner');
  if (!body || !String(body).trim()) return skip('empty');
  if (STAMP_RE.test(body)) return skip('already stamped');
  if (carriesFooter(body)) return skip('footer');
  if (endsInsideFence(body)) return skip('open fence');
  const clock = primaClock(when);
  if (!clock) return skip('no time');
  const eol = String(body).includes('\r\n') ? '\r\n' : '\n';
  const text = String(body).replace(/\s+$/, '');
  return { action: 'stamp', clock, body: `${text}${eol}${eol}prima-clock: ${clock} UTC (stamped on submit)` };
}

// What each event carries, how to read the latest body, and how to save it.
function target({ github, context }) {
  const { owner, repo } = context.repo;
  const p = context.payload;
  if (context.eventName === 'pull_request_review') {
    const ref = { owner, repo, pull_number: p.pull_request.number, review_id: p.review.id };
    return {
      item: p.review, when: p.review.submitted_at,
      latest: async () => (await github.rest.pulls.getReview(ref)).data.body,
      save: (body) => github.rest.pulls.updateReview({ ...ref, body }),
    };
  }
  if (context.eventName === 'pull_request_review_comment') {
    const ref = { owner, repo, comment_id: p.comment.id };
    return {
      item: p.comment, when: p.comment.created_at,
      latest: async () => (await github.rest.pulls.getReviewComment(ref)).data.body,
      save: (body) => github.rest.pulls.updateReviewComment({ ...ref, body }),
    };
  }
  const ref = { owner, repo, comment_id: p.comment.id };
  return {
    item: p.comment, when: p.comment.created_at,
    latest: async () => (await github.rest.issues.getComment(ref)).data.body,
    save: (body) => github.rest.issues.updateComment({ ...ref, body }),
  };
}

async function apply({ github, context, core }) {
  const t = target({ github, context });
  const body = await t.latest();
  const d = decide({
    body, when: t.when, login: t.item.user.login, type: t.item.user.type,
    association: t.item.author_association, owner: context.repo.owner,
  });
  if (d.action === 'skip') {
    core.info(`Not stamped: ${d.reason}.`);
    return;
  }
  try {
    await t.save(d.body);
    core.info(`Stamped ${d.clock} UTC.`);
  } catch (err) {
    // GitHub may refuse an edit to the owner's text (a review summary, or a fork PR with a read-only token).
    core.warning(`The stamp was not saved (${err.status || 'no status'}): ${err.message}`);
  }
}

module.exports = { apply, decide, primaClock };
